      ...MilestoneFields
    }
  }
}

fragment MilestoneFields on Milestone {
  id
  title
  closed
  closedAt
  dueOn
  progressPercentage
  url
}

efc9e04436f93f4519c90415318a463209fe1138.query:
query SearchAssigneesInIssue($owner: String!, $name: String!, $number: Int!, $query: String!, $first: Int!) {
  repository(owner: $owner, name: $name) {
    issueOrPullRequest(number: $number) {
      ... on Assignable {
        suggestedActors(first: $first, query: $query) {
          nodes {
            __typename
            ... on User {
              id
              login
              name
              profileResourcePath
              avatarUrl(size: 64)
            }
            ... on Bot {
              id
              login
              name
              profileResourcePath
              avatarUrl(size: 64)
              isCopilot
              isAgent
              displayName
              needsAuthorization
            }
            ... on Mannequin {
              id
              login
              name: login
              profileResourcePath: url
              avatarUrl(size: 64)
            }
            ... on Organization {
              id
              login
              name
              profileResourcePath: url
              avatarUrl(size: 64)
            }
          }
          totalCount
        }
      }
    }
  }
}

28be3a3589e199011317fcc8dbf15ae2467e0b43.query:
query SearchAssigneesInRepo($owner: String!, $name: String!, $query: String, $loginNames: String, $first: Int!, $capabilities: [RepositorySuggestedActorFilter!]!) {
  repository(owner: $owner, name: $name) {
    suggestedActors(first: $first, query: $query, loginNames: $loginNames, capabilities: $capabilities) {
      nodes {
        __typename
        id
        login
        name
        profileResourcePath
        avatarUrl(size: 64)
        ... on User {
          databaseId
        }
        ... on Bot {
          databaseId
          isCopilot
          isAgent
          displayName
          needsAuthorization
        }
      }
      totalCount
    }
  }
}

5cd28e7d2d4177827fcc089dfdb059721be90df0.query:
query SearchIssueTypes($owner: String!, $repo: String!) {
  repository(owner: $owner, name: $repo) {
    issueTypes(first: 25) {
      edges {
        node {
          id
          name
          isEnabled
          description
          color
          pinnedFields {
            __typename
            ... on IssueFieldText {
              id
              name
              dataType
            }
            ... on IssueFieldSingleSelect {
              id
              name
              dataType
            }
            ... on IssueFieldDate {
              id
              name
              dataType
            }
            ... on IssueFieldNumber {
              id
              name
              dataType
            }
            ... on IssueFieldMultiSelect {
              id
              name
              dataType
            }
          }
        }
      }
      totalCount
    }
  }
}

507750943a85895cf1a0d814283b40df6703588e.query:
query SearchLabels($owner: String!, $repo: String!, $count: Int!, $query: String = "", $labelNames: String = "", $shouldQueryByNames: Boolean = false) {
  repository(owner: $owner, name: $repo) {
    id
    labels(first: $count, query: $query, orderBy: {field: NAME, direction: ASC}) {
      totalCount
      nodes {
        ...LabelFields
      }
    }
    labelsByNames: labels(names: $labelNames, first: $count, orderBy: {field: NAME, direction: ASC}) @include(if: $shouldQueryByNames) {
      nodes {
        ...LabelFields
      }
    }
  }
}

fragment LabelFields on Label {
  id
  color
  name
  nameHTML
  description
  url
}

8bfb8d5dced8d160c5e46d13ac616c638571481d.query:
query SearchMilestones($owner: String!, $repo: String!, $count: Int!, $query: String) {
  repository(owner: $owner, name: $repo) {
    id
    milestones(first: $count, query: $query, orderBy: {field: UPDATED_AT, direction: DESC}, orderByStates: [OPEN, CLOSED]) {
      nodes {
        ...MilestoneFields
      }
    }
  }
}

fragment MilestoneFields on Milestone {
  id
  title
  closed
  closedAt
  dueOn
  progressPercentage
  url
}

307bde94b443b8074dea8abc3d1ba6db23f7e8f4.query:
query SearchProjects($owner: String!, $repo: String!, $query: String) {
  repository(owner: $owner, name: $repo) {
    projectsV2(first: 5, query: $query, orderBy: {field: RELEVANCE, direction: DESC}, useFullTermQuery: true) {
      nodes {
        ...ProjectPickerRelay
      }
    }
    recentProjects(first: 5) {
      edges {
        node {
          ...ProjectPickerRelay
        }
      }
    }
    owner {
      ... on Organization {
        projectsV2(first: 5, orderBy: {field: RELEVANCE, direction: DESC}, query: $query, useFullTermQuery: true) {
          edges {
            node {
              ...ProjectPickerRelay
            }
          }
        }
        recentProjects(first: 5) {
          edges {
            node {
              ...ProjectPickerRelay
            }
          }
        }
      }
      ... on User {
        projectsV2(first: 5, orderBy: {field: RELEVANCE, direction: DESC}, query: $query, useFullTermQuery: true) {
          edges {
            node {
              ...ProjectPickerRelay
            }
          }
        }
        recentProjects(first: 5) {
          edges {
            node {
              ...ProjectPickerRelay
            }
          }
        }
      }
    }
  }
}

fragment ProjectPickerRelay on ProjectV2 {
  id
  title
  closed
  number
  url
  viewerCanUpdate
  hasReachedItemsLimit
  __typename
}

